def check_rate_limit(redis_client, sha: str, api_key: str, cap: int, rate: float, cost: int = 1):
    key = f"rl:{{{api_key}}}"
    try:
        allowed, rem, retry_ms = redis_client.evalsha(sha, 1, key, cap, rate, cost)
    except Exception as e:
        if "NOSCRIPT" in str(e):
            allowed, rem, retry_ms = redis_client.eval(TOKEN_BUCKET_LUA, 1, key, cap, rate, cost)
        else:
            raise
    return bool(allowed), int(rem), int(retry_ms)

import time

class GatewayRateLimiter:
    def __init__(self, redis_client, sha: str, num_nodes: int = 40):
        self.redis = redis_client
        self.sha = sha
        self.num_nodes = num_nodes
        self.l1_deny: dict[str, float] = {}  # api_key -> blocked_until_ms

    def allow(self, api_key: str, cap: int, rate: float) -> tuple[bool, int]:
        now = time.monotonic() * 1000.0
        if self.l1_deny.get(api_key, 0.0) > now:
            return False, 100
        try:
            ok, rem, retry_ms = check_rate_limit(self.redis, self.sha, api_key, cap, rate)
            if not ok:
                self.l1_deny[api_key] = now + min(100.0, float(retry_ms))
            return ok, retry_ms
        except Exception:
            # Fail-open with local fallback or allow; here fail-open on Redis timeout
            return True, 0

# Async regional quota allocation: weight regional rate by trailing 10s traffic share
def allocate_regional_rates(global_rate: float, regional_rps: dict[str, float]) -> dict[str, float]:
    total = sum(regional_rps.values()) or 1.0
    return {region: max(global_rate * 0.1, global_rate * (rps / total)) for region, rps in regional_rps.items()}
